# illustrative (httpx client, provider-agnostic)
@activity("charge_payment")
async def charge_payment(ctx, amount, card_token):
    try:
        r = await http.post("/charges", json={"amount": amount, "source": card_token},
                            headers={"Idempotency-Key": ctx.idempotency_key}, timeout=10)
    except httpx.TransportError as e:
        raise ConnectionError(str(e))                    # retryable; the key makes the retry safe
    if r.status_code in (402, 400):
        raise NonRetryableError(r.json().get("decline_code", "declined"))
    r.raise_for_status()                                 # 5xx/429 -> retry with backoff
    return {"charge_id": r.json()["id"], "amount": amount}

# real, flowengine/runtime.py
async def _settle(task: asyncio.Task, ctx: WorkflowContext) -> None:
    last = None
    while True:
        for _ in range(3):
            await asyncio.sleep(0)
        state = (task.done(), len(ctx.commands), sum(f.done() for f in ctx._futures.values()))
        if state == last or task.done():
            return
        last = state

