# flowengine/examples/workflows.py
@workflow("trial_subscription")
async def trial_subscription(ctx, inp):
    acct = await ctx.execute_activity("create_account", inp["email"], retry=FAST)
    await ctx.execute_activity("send_email", inp["email"], "trial_started", retry=FAST)
    pm = await ctx.wait_signal("payment_method_added", timeout=inp["trial_seconds"])
    if pm is None:
        await ctx.execute_activity("send_email", inp["email"], "trial_expired", retry=FAST)
        return {"status": "expired", "account_id": acct["account_id"]}
    try:
        charge = await ctx.execute_activity("charge_payment", inp["price"], pm["card"], retry=FAST)
    except ActivityError as e:
        await ctx.execute_activity("send_email", inp["email"], "payment_failed", retry=FAST)
        return {"status": "payment_failed", "reason": e.message}
    await ctx.execute_activity("send_email", inp["email"], "subscribed", retry=FAST)
    return {"status": "active", "charge_id": charge["charge_id"]}

