    await store.signal(sm, "tr-paid", "payment_method_added", {"card": "ok"})          # early: buffered
    await store.signal(sm, "tr-declined", "payment_method_added", {"card": "declined"})
    async with worker(sm):
        paid, exp, dec = [await wait_status(sm, w) for w in ("tr-paid", "tr-expired", "tr-declined")]
    assert paid["result"]["status"] == "active" and exp["result"]["status"] == "expired"
    assert dec["result"] == {"status": "payment_failed", "reason": "card declined"}
